/*
Institutions, their structure tree (+ closure), buildings, groups, positions/appointments, and the
person bindings (enrollments, dorm stays). Reads gate on `education.read`; structure writes on
`education.manage`; position/appointment writes on `education.position.manage`; person-binding
writes on `education.enrollment.manage`; catalog-kind writes on `education.catalog.manage`. Writes
are audited in-process (D-Audit).
*/
type EducationServiceClientWithAuth interface {
	ListInstitutionKinds(ctx context.Context) (InstitutionKindList, error)
	// Create or update (by code) an institution-kind catalog entry.
	UpsertInstitutionKind(ctx context.Context, requestArg UpsertCatalogKindRequest) (InstitutionKind, error)
	// The `university` domain's unit-kind catalog (owned by the tenant service — M41).
	ListUnitKinds(ctx context.Context) (UnitKindList, error)
	ListDegreeLevels(ctx context.Context) (DegreeLevelList, error)
	CreateInstitution(ctx context.Context, requestArg CreateInstitutionRequest) (Institution, error)
	/*
	   List institutions, token-paginated, optionally filtered by the facet vocabulary (M58 ticket
	   5 / D-ObjectFacets). Shadow-gated: an institution IS a `university`-domain tenant
	   organization (M41 / D-UnifiedOrgGraph), so it carries that organization's public/shadow bit
	   and is trimmed by the same rule `listOrganizations` applies. Gated by education.read.

	   Every filter arg here is also an arg of `institutionStats`, and a chart segment's key is a
	   usable value for the arg it came from — that is what makes a dashboard and a list two
	   renderings of one request state.
	*/
	ListInstitutions(ctx context.Context, queryArg *string, kindIdArg *string, countryIdArg *string, foundedOnFromArg *string, foundedOnToArg *string, stateArg *string, pageSizeArg *int, pageTokenArg *string) (InstitutionPage, error)
	/*
	   Facet distributions over the institution registry — the dashboard half of the institution
	   facet vocabulary (M58 ticket 5 / D-ObjectFacets). Takes exactly the filter args
	   `listInstitutions` takes, minus paging, so a dashboard and a list are two renderings of one
	   request state.

	   The path is `/stats/institutions` rather than `/institutions/stats` because the server's
	   router rejects a literal path segment that is a sibling of `{institutionId}` — see the
	   route-conflict guard in `internal/platform/transport`.
	*/
	InstitutionStats(ctx context.Context, facetsArg *string, queryArg *string, kindIdArg *string, countryIdArg *string, foundedOnFromArg *string, foundedOnToArg *string, stateArg *string) (InstitutionStats, error)
	GetInstitution(ctx context.Context, institutionIdArg string) (Institution, error)
	UpdateInstitution(ctx context.Context, institutionIdArg string, requestArg UpdateInstitutionRequest) (Institution, error)
	DeleteInstitution(ctx context.Context, institutionIdArg string) error
	CreateUnit(ctx context.Context, institutionIdArg string, requestArg CreateUnitRequest) (EducationUnit, error)
	// All active units of an institution with their closure depth from the nearest root.
	ListUnits(ctx context.Context, institutionIdArg string) (EducationUnitList, error)
	GetUnit(ctx context.Context, unitIdArg string) (EducationUnit, error)
	UpdateUnit(ctx context.Context, unitIdArg string, requestArg UpdateUnitRequest) (EducationUnit, error)
	// Move a unit under a new parent, recomputing the closure. Returns Education:UnitCycleDetected on a cycle.
	ReparentUnit(ctx context.Context, unitIdArg string, requestArg ReparentUnitRequest) (EducationUnit, error)
	CreateBuilding(ctx context.Context, institutionIdArg string, requestArg CreateBuildingRequest) (Building, error)
	ListBuildings(ctx context.Context, institutionIdArg string) (BuildingList, error)
	GetBuilding(ctx context.Context, buildingIdArg string) (Building, error)
	UpdateBuilding(ctx context.Context, buildingIdArg string, requestArg UpdateBuildingRequest) (Building, error)
	DeleteBuilding(ctx context.Context, buildingIdArg string) error
	CreateGroup(ctx context.Context, unitIdArg string, requestArg CreateGroupRequest) (Group, error)
	ListGroups(ctx context.Context, unitIdArg string) (GroupList, error)
	GetGroup(ctx context.Context, groupIdArg string) (Group, error)
	UpdateGroup(ctx context.Context, groupIdArg string, requestArg UpdateGroupRequest) (Group, error)
	DeleteGroup(ctx context.Context, groupIdArg string) error
	CreatePosition(ctx context.Context, institutionIdArg string, requestArg CreatePositionRequest) (EducationPosition, error)
	ListPositions(ctx context.Context, institutionIdArg string, stateArg *string, pageSizeArg *int, pageTokenArg *string) (PositionPage, error)
	GetPosition(ctx context.Context, positionIdArg string) (EducationPosition, error)
	UpdatePosition(ctx context.Context, positionIdArg string, requestArg UpdatePositionRequest) (EducationPosition, error)
	AbolishPosition(ctx context.Context, positionIdArg string) (EducationPosition, error)
	// Fill a vacant position. Returns Education:PositionAlreadyFilled if already filled.
	FillPosition(ctx context.Context, positionIdArg string, requestArg FillPositionRequest) (Appointment, error)
	EndAppointment(ctx context.Context, appointmentIdArg string, requestArg EndAppointmentRequest) (Appointment, error)
	// Read-only list of the education positions a person holds, enriched with title + institution.
	ListPersonAppointments(ctx context.Context, personIdArg string) (PersonAppointmentList, error)
	ListEnrollments(ctx context.Context, personIdArg string) (EnrollmentList, error)
	CreateEnrollment(ctx context.Context, personIdArg string, requestArg UpsertEnrollmentRequest) (Enrollment, error)
	UpdateEnrollment(ctx context.Context, personIdArg string, enrollmentIdArg string, requestArg UpsertEnrollmentRequest) (Enrollment, error)
	DeleteEnrollment(ctx context.Context, personIdArg string, enrollmentIdArg string) error
	ListDormitoryStays(ctx context.Context, personIdArg string) (DormitoryStayList, error)
	CreateDormitoryStay(ctx context.Context, personIdArg string, requestArg UpsertDormitoryStayRequest) (DormitoryStay, error)
	UpdateDormitoryStay(ctx context.Context, personIdArg string, stayIdArg string, requestArg UpsertDormitoryStayRequest) (DormitoryStay, error)
	DeleteDormitoryStay(ctx context.Context, personIdArg string, stayIdArg string) error
}

